/-- Finite continuous convex normalized divergence generators. -/
def AdmissibleGenerator (f : ℝ → ℝ) : Prop :=
  ContinuousOn f (Set.Ici 0) ∧ ConvexOn ℝ (Set.Ici 0) f ∧ f 1 = 0

/-- A real sequence is eventually bounded below by a target up to `o(1)`. -/
def AsymptoticAtLeast (target : ℝ) (u : ℕ → ℝ) : Prop :=
  ∃ r : ℕ → ℝ, Tendsto r atTop (nhds 0) ∧ ∀ᶠ n in atTop, target - r n ≤ u n

/-- Rectangularity of the bands emitted by a directional-inference procedure. -/
def DirectionalHandle (band : FiniteSampleBand) : Prop :=
  IsRectangularBand band

/-- A probability vector on a finite alphabet. -/
def FiniteProbabilityVector {J : Type} [Fintype J] (p : J → ℝ) : Prop :=
  (∀ j, p j ∈ Set.Icc 0 1) ∧ ∑ j, p j = 1

/-- A valid familywise miscoverage level. -/
def MiscoverageLevel (alpha : ℝ) : Prop :=
  alpha ∈ Set.Ioo 0 1

/-- Mutual absolute continuity for two measures. -/
def MutuallyAC {Y : Type*} [MeasurableSpace Y] (P Q : Measure Y) : Prop :=
  P.AbsolutelyContinuous Q ∧ Q.AbsolutelyContinuous P

/-- A generic probability coordinate. -/
def ProbabilityCoordinate (q : ℝ) : Prop :=
  q ∈ Set.Icc 0 1

/-- The propensity-induced cap. -/
def PropensityCap (e c : ℝ) : Prop :=
  StrictPositivity e ∧ c = 1 / e ∧ 1 < c

/-- Exactness over every standard Borel carrier. -/
def UniversalMutualExact (f : ℝ → ℝ) (e : ℝ) : Prop :=
  ∀ (Z : Type) (mZ : MeasurableSpace Z), @StandardBorelSpace Z mZ →
    @MutualExactAt Z mZ f e

/-- One-sided exactness over every standard Borel carrier. -/
def UniversalOneSidedExact (f : ℝ → ℝ) (e : ℝ) : Prop :=
  ∀ (Z : Type) (mZ : MeasurableSpace Z), @StandardBorelSpace Z mZ →
    @OneSidedExactAt Z mZ f e

/-- Number of observations in an arm. -/
def armCount {n : ℕ} (S : ObservedSample n) (a : Bool) : ℕ :=
  ∑ i, if (S i).1 = a then 1 else 0

/-- The probability of a treatment arm. -/
def armPropensity {Y : Type*} [MeasurableSpace Y] (w : BowWitness Y) (a : Bool) : ℝ :=
  (w.law {z | treatment z = a}).toReal

/-- Generators affine-equivalent to the cap hinge. -/
def hingeClassSet (c : ℝ) : Set (ℝ → ℝ) :=
  {f | HingeClass c f}

/-- The finite-sample simultaneous endpoint band. -/
-- @node: def:honest-band
noncomputable def honestBand {Omega : Type*}
    (Z : ℕ → Omega → Bool × ℝ) (a : Bool) (n : ℕ)
    (alpha : ℝ) (omega : Omega) (y : ℝ) : Set (ℝ × ℝ) :=
  let S : ObservedSample n := fun i => Z i omega
  if armCount S a = 0 then Set.Icc 0 1 ×ˢ Set.Icc 0 1 else
    let deltaE := Real.sqrt (Real.log (4 / alpha) / (2 * n))
    let deltaF := Real.sqrt (Real.log (4 / alpha) / (2 * armCount S a))
    let Ie : Set (Set.Icc (0 : ℝ) 1) :=
      {eta | eta.1 ∈ Set.Icc (empiricalArmPropensity S a - deltaE)
        (empiricalArmPropensity S a + deltaE)}
    let IF : Set (Set.Icc (0 : ℝ) 1) :=
      {p | p.1 ∈ Set.Icc (empiricalArmCDF S a y - deltaF)
        (empiricalArmCDF S a y + deltaF)}
    rectangularHull ((fun ep => cdfEndpoints ep.1 ep.2) '' (Ie ×ˢ IF))

/-- The potential outcome selected by an arm. -/
def potentialOutcome {Y : Type*} (a : Bool) (z : Bool × Y × Y) : Y :=
  if a then z.2.2 else z.2.1

/-- Read the `i`th coordinate of a finite sample, using a harmless value outside
the first `n` indices. -/
def sampleCoordinate (n i : ℕ) (S : ObservedSample n) : Bool × ℝ :=
  if h : i < n then S ⟨i, h⟩ else (false, 0)
